type Block = [string, string];
type FoundationPage = { id: string; title: string; subtitle: string; intro: string; blocks: Block[]; tip: [string, string] };
type TopicPage = { id: string; title: string; description: string; spot: string; rules: string[]; steps: string[]; traps: string[]; example?: [string, string] };
type GuideGroup = { id: string; label: string; icon: string; topics: TopicPage[] };
export type GuideSection = { short: string; label: string; color: string; deep: string; tint: string; tagline: string; stats: [string, string][]; foundations: FoundationPage[]; groups: GuideGroup[]; official?: string };

const F = (id: string, title: string, subtitle: string, intro: string, blocks: Block[], tip: [string, string]): FoundationPage => ({ id, title, subtitle, intro, blocks, tip });
const T = (id: string, title: string, description: string, spot: string, rules: string[], steps: string[], traps: string[], example?: [string, string]): TopicPage => ({ id, title, description, spot, rules, steps, traps, example });

