export const getGuidePages = (section: GuideSection): string[] => [
  "overview",
  ...section.groups.flatMap(g => g.topics.map(t => t.id)),
];

export const findFoundation = (section: GuideSection, pageId: string) =>
  section.foundations.find(p => p.id === pageId);

export const findTopic = (section: GuideSection, pageId: string) =>
  section.groups.flatMap(g => g.topics).find(t => t.id === pageId);

export const getGuidePageTitle = (section: GuideSection, pageId: string): string =>
  pageId === "overview"
    ? `${section.short} study guide`
    : findFoundation(section, pageId)?.title ?? findTopic(section, pageId)?.title ?? "Study guide";
